CREATE TABLE "AgentCheckpoint" ("runId" TEXT NOT NULL PRIMARY KEY, "state" TEXT NOT NULL, "provider" TEXT NOT NULL, "expiresAt" DATETIME NOT NULL, FOREIGN KEY ("runId") REFERENCES "AgentRun" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "AgentConfirmation" ("stepId" TEXT NOT NULL PRIMARY KEY, "status" TEXT NOT NULL DEFAULT 'pending', "tainted" BOOLEAN NOT NULL DEFAULT false, "undoId" TEXT, "expiresAt" DATETIME NOT NULL, FOREIGN KEY ("stepId") REFERENCES "AgentStep" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "AgentSpend" ("day" TEXT NOT NULL PRIMARY KEY, "micros" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "AgentReservation" ("runId" TEXT NOT NULL PRIMARY KEY, "day" TEXT NOT NULL, "micros" INTEGER NOT NULL, "settled" BOOLEAN NOT NULL DEFAULT false, FOREIGN KEY ("runId") REFERENCES "AgentRun" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "AgentAudit" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "runId" TEXT NOT NULL, "tool" TEXT NOT NULL, "arguments" TEXT NOT NULL, "resultSize" INTEGER NOT NULL DEFAULT 0, "durationMs" INTEGER NOT NULL DEFAULT 0, "status" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "AgentAudit_createdAt_idx" ON "AgentAudit" ("createdAt");
CREATE TABLE "MemoryUndo" ("id" TEXT NOT NULL PRIMARY KEY, "ownerId" TEXT NOT NULL, "category" TEXT NOT NULL, "memoryId" TEXT NOT NULL, "savedAt" DATETIME NOT NULL, "previous" TEXT, "expiresAt" DATETIME NOT NULL, "used" BOOLEAN NOT NULL DEFAULT false);
CREATE INDEX "MemoryUndo_ownerId_idx" ON "MemoryUndo" ("ownerId");
